def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 5) and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] not in (0,5) and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                rs = [y for y,x in cells]; cs = [x for y,x in cells]
                comps.append((min(rs), max(rs), min(cs), max(cs)))

    # Find contiguous runs of the frame color 5, then extend the adjacent
    # colored seed strip across the run, repeating its pattern if necessary.
    vertical = []
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1; continue
            a = r
            while r < h and grid[r][c] == 5: r += 1
            if r-a >= 2: vertical.append((a, r-1, c))
    for a, b, c in vertical:
        for t, u, l, rr in comps:
            if l == c+1 and t <= b and u >= a:
                for y in range(a, b+1):
                    sy = t + (y-a) % (u-t+1)
                    for x in range(l, rr+1): out[y][x] = grid[sy][x]

    horizontal = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1; continue
            a = c
            while c < w and grid[r][c] == 5: c += 1
            if c-a >= 2: horizontal.append((r, a, c-1))
    for r, a, b in horizontal:
        for t, u, l, rr in comps:
            if t == r+1 and l <= b and rr >= a:
                for y in range(t, u+1):
                    for x in range(a, b+1):
                        sx = l + (x-a) % (rr-l+1)
                        out[y][x] = grid[y][sx]
    return out
